<template><view class="page"><nav-bar title="试卷基本信息" :showBack="true" placeholder/><view class="form"><view class="field"><text>试卷名称</text><input v-model="form.name" placeholder="例如：Python期末试卷" maxlength="60"/></view><view class="field"><text>所属科目</text><input v-model="form.subject" placeholder="请输入科目"/></view><view class="field"><text>试卷分类</text><picker :range="categories" @change="form.category=categories[$event.detail.value]"><view class="picker">{{form.category||'请选择分类'}} <text>›</text></view></picker></view><view class="field"><text>考试时长（分钟）</text><input v-model.number="form.duration" type="number" placeholder="可选"/></view><view class="field"><text>试卷备注</text><textarea v-model="form.remark" placeholder="填写试卷说明（可选）"/></view><button class="primary" :loading="saving" @click="next">下一步：选择试题</button></view></view></template>
<script>import NavBar from '@/components/nav-bar/nav-bar.vue';import {createPaper,updatePaper,getPaper} from '@/api/paper.js';export default{components:{NavBar},data(){return{paperId:null,source:'public',saving:false,categories:['期末考试','章节测试','模拟练习','面试练习','自定义'],form:{name:'',subject:'',category:'',duration:'',remark:''}}},onLoad(q){this.paperId=q.paperId||null;this.source=q.source||'public';if(this.paperId)this.load()},methods:{async load(){const r=await getPaper(this.paperId);this.form={name:r.data.name,subject:r.data.subject,category:r.data.category,duration:r.data.duration||'',remark:r.data.remark||''}},async next(){if(!this.form.name.trim()||!this.form.subject.trim()||!this.form.category){uni.showToast({title:'请填写试卷名称、科目和分类',icon:'none'});return}this.saving=true;try{const r=this.paperId?await updatePaper(this.paperId,this.form):await createPaper(this.form);this.paperId=r.data.id;uni.navigateTo({url:`/subpackage_ai/paperSelect/paperSelect?paperId=${this.paperId}&source=${this.source}`})}finally{this.saving=false}}}}</script>
<style scoped lang="scss">.page{min-height:100vh;background:#f5f8fc}.form{padding:24rpx}.field{background:#fff;border-radius:18rpx;padding:22rpx 24rpx;margin-bottom:16rpx}.field>text{display:block;font-size:25rpx;color:#33415a;margin-bottom:14rpx}.field input,.field textarea{width:100%;font-size:28rpx;color:#27364d}.field textarea{height:130rpx}.picker{font-size:28rpx;color:#27364d;display:flex;justify-content:space-between}.primary{margin-top:40rpx;background:#4d78e8;color:#fff;border-radius:50rpx;font-size:29rpx}</style>
